#!/usr/bin/env bun
/**
 * Fake `codex app-server` speaking the v2 JSON-RPC subset the CodexDriver uses,
 * shaped after the schema generated by `codex app-server generate-json-schema`
 * (codex-cli 0.156.1). Scenarios are selected by markers in the turn input text.
 *
 * Every request and every reply to a server-initiated request is appended to
 * $FAKE_CODEX_LOG (one JSON object per line) so tests can assert wire shapes.
 */

import * as fs from "node:fs";

const logPath = process.env.FAKE_CODEX_LOG;
const log = (entry: unknown) => { if (logPath) fs.appendFileSync(logPath, JSON.stringify(entry) + "\n"); };
const out = (msg: unknown) => { process.stdout.write(JSON.stringify(msg) + "\n"); };
const notify = (method: string, params: unknown) => out({ jsonrpc: "2.0", method, params });
const reply = (id: unknown, result: unknown) => out({ jsonrpc: "2.0", id, result });
const replyError = (id: unknown, code: number, message: string) => out({ jsonrpc: "2.0", id, error: { code, message } });

let threadCounter = 0;
let turnCounter = 0;
let activeThread: string | null = null;
let activeTurn: string | null = null;
let steered: string[] = [];
let interruptRequested = false;
let wakeSlowTurn: (() => void) | null = null;
let serverRequestId = 1000;
const pendingServerRequests = new Map<number, (response: { result?: unknown; error?: unknown }) => void>();

function serverRequest(method: string, params: unknown): Promise<{ result?: unknown; error?: unknown }> {
  return new Promise((resolve) => {
    const id = ++serverRequestId;
    pendingServerRequests.set(id, resolve);
    out({ jsonrpc: "2.0", id, method, params });
  });
}

function inputText(params: any): string {
  return (params.input ?? []).map((i: any) => i.text ?? "").join(" ");
}

async function runTurn(threadId: string, turnId: string, text: string): Promise<void> {
  notify("thread/status/changed", { threadId, status: { type: "active", activeFlags: [] } });
  notify("turn/started", { threadId, turn: { id: turnId, status: "inProgress", items: [] } });

  let status: "completed" | "failed" | "interrupted" = "completed";
  let error: unknown = null;
  const now = Date.now();

  const ask = async (method: string, params: unknown) => {
    const response = await serverRequest(method, params);
    log({ serverRequest: method, response });
  };

  if (text.includes("SCENARIO:fail")) {
    status = "failed";
    error = { message: "boom: simulated model error" };
  } else if (text.includes("SCENARIO:permissions")) {
    await ask("item/permissions/requestApproval", {
      threadId, turnId, itemId: "item_perm", cwd: process.cwd(), startedAtMs: now, reason: "needs /tmp",
      permissions: { fileSystem: { read: [{ type: "path", path: "/tmp" }], write: [{ type: "path", path: "/tmp" }] }, network: { enabled: true } },
    });
  } else if (text.includes("SCENARIO:userinput")) {
    await ask("item/tool/requestUserInput", {
      threadId, turnId, itemId: "item_q", isBlocking: true,
      questions: [{ id: "q1", header: "Choice", question: "Which option?", isOther: false, isSecret: false, options: [] }],
    });
  } else if (text.includes("SCENARIO:elicitation")) {
    await ask("mcpServer/elicitation/request", { serverName: "some-server", threadId, turnId, message: "Confirm?", requestedSchema: { type: "object", properties: {} } });
  } else if (text.includes("SCENARIO:command")) {
    await ask("item/commandExecution/requestApproval", { threadId, turnId, itemId: "item_cmd", command: "rm -rf build", startedAtMs: now });
  } else if (text.includes("SCENARIO:filechange")) {
    await ask("item/fileChange/requestApproval", { threadId, turnId, itemId: "item_fc", startedAtMs: now });
  } else if (text.includes("SCENARIO:dyntool")) {
    await ask("item/tool/call", { threadId, turnId, callId: "call_1", tool: "custom_tool", arguments: {} });
  } else if (text.includes("SCENARIO:auth")) {
    await ask("account/chatgptAuthTokens/refresh", { reason: "expired", previousAccountId: null });
  } else if (text.includes("SCENARIO:legacy")) {
    await ask("execCommandApproval", { threadId, turnId, itemId: "item_legacy", command: ["ls"], cwd: process.cwd() });
  } else if (text.includes("SCENARIO:slow")) {
    const ms = parseInt(text.match(/SCENARIO:slow:(\d+)/)?.[1] ?? "8000", 10);
    notify("item/started", { threadId, turnId, startedAtMs: now, item: { type: "commandExecution", id: "cmd_1", command: "sleep", status: "inProgress" } });
    await new Promise<void>((resolve) => { wakeSlowTurn = resolve; setTimeout(resolve, ms); });
    wakeSlowTurn = null;
    notify("item/completed", { threadId, turnId, completedAtMs: Date.now(), item: { type: "commandExecution", id: "cmd_1", command: "sleep", status: interruptRequested ? "interrupted" : "completed" } });
    if (interruptRequested) status = "interrupted";
  }

  if (status === "completed") {
    const message = `ack:${text}${steered.length > 0 ? ` | steered:${steered.join("|")}` : ""}`;
    notify("item/agentMessage/delta", { threadId, turnId, itemId: "msg_1", delta: message.slice(0, 4) });
    notify("item/agentMessage/delta", { threadId, turnId, itemId: "msg_1", delta: message.slice(4) });
    notify("item/completed", { threadId, turnId, completedAtMs: Date.now(), item: { type: "agentMessage", id: "msg_1", text: message } });
    notify("thread/tokenUsage/updated", {
      threadId, turnId,
      tokenUsage: {
        last: { inputTokens: 120, cachedInputTokens: 10, outputTokens: 30, reasoningOutputTokens: 0, totalTokens: 150, cacheWriteInputTokens: 0 },
        total: { inputTokens: 120 * turnCounter, cachedInputTokens: 10 * turnCounter, outputTokens: 30 * turnCounter, reasoningOutputTokens: 0, totalTokens: 150 * turnCounter, cacheWriteInputTokens: 0 },
        modelContextWindow: 200000,
      },
    });
  }

  steered = [];
  interruptRequested = false;
  activeTurn = null;
  notify("turn/completed", { threadId, turn: { id: turnId, status, error, items: [], completedAt: Date.now() } });
  notify("thread/status/changed", { threadId, status: { type: "idle" } });
}

function handle(msg: any): void {
  if (msg.id !== undefined && msg.method === undefined) {
    const pending = pendingServerRequests.get(msg.id);
    if (pending) {
      pendingServerRequests.delete(msg.id);
      pending({ result: msg.result, error: msg.error });
    }
    return;
  }

  const { id, method, params = {} } = msg;
  if (method !== "initialized") log({ request: method, params });

  switch (method) {
    case "initialize":
      return reply(id, { userAgent: "fake-codex-app-server/0.156.1" });
    case "initialized":
      return;
    case "thread/start": {
      activeThread = `thr_${++threadCounter}`;
      return reply(id, { thread: { id: activeThread, cwd: params.cwd ?? process.cwd() }, approvalsReviewer: "user" });
    }
    case "thread/resume": {
      activeThread = params.threadId;
      return reply(id, { thread: { id: activeThread }, approvalsReviewer: "user" });
    }
    case "thread/list":
      return reply(id, { data: [], nextCursor: null });
    case "account/read":
      return reply(id, { account: { type: "chatgpt", email: "fake@example.com", planType: "plus" }, requiresOpenaiAuth: true });
    case "account/rateLimits/read":
      // Like older app-servers, whose request takes no params at all
      if (params !== null && params !== undefined && Object.keys(params).length) return replyError(id, -32600, "Invalid request: invalid type: map, expected unit");
      if (process.env.FAKE_CODEX_LOGGED_OUT === "1") return replyError(id, -32600, "codex account authentication required to read rate limits");
      return reply(id, { rateLimits: {
        limitId: "codex", planType: "plus",
        primary: { usedPercent: 63, windowDurationMins: 300, resetsAt: 1893474000 },
        secondary: { usedPercent: 21, windowDurationMins: 10080, resetsAt: 1893906000 },
      } });
    case "turn/start": {
      if (activeTurn) return replyError(id, -32600, "a turn is already active");
      const turnId = `turn_${++turnCounter}`;
      activeTurn = turnId;
      reply(id, { turn: { id: turnId, status: "inProgress", items: [] } });
      void runTurn(params.threadId, turnId, inputText(params));
      return;
    }
    case "turn/steer": {
      if (!activeTurn || params.expectedTurnId !== activeTurn) return replyError(id, -32600, "no active turn matching expectedTurnId");
      steered.push(inputText(params));
      return reply(id, { turnId: activeTurn });
    }
    case "turn/interrupt": {
      if (!activeTurn || params.turnId !== activeTurn) return replyError(id, -32600, "INVALID_REQUEST: turn is not active");
      interruptRequested = true;
      wakeSlowTurn?.();
      return reply(id, {});
    }
    default:
      return replyError(id, -32601, `method not found: ${method}`);
  }
}

let buffer = "";
process.stdin.on("data", (chunk) => {
  buffer += chunk.toString();
  const lines = buffer.split("\n");
  buffer = lines.pop() ?? "";
  for (const line of lines) {
    if (!line.trim()) continue;
    try { handle(JSON.parse(line)); } catch { /* ignore malformed */ }
  }
});
process.stdin.on("end", () => process.exit(0));
